sys_script.script:
(function executeRule(current, previous) {
    var code = current.getValue('u_customer');

    var gr = new GlideRecord('x_birl3_clm_clm_customer_master1');
    gr.addQuery('customer_code_sap', code);
   // gr.addQuery('is_active', true);
    gr.setLimit(1);
    gr.query();

    if (!gr.hasNext()) {
        current.setAbortAction(true);   // skip insert if not in master
    }
})(current, previous);
